let content=params.get('content')==='studies'?'studies':params.get('content')==='files'||params.has('kind')?'files':'studies',kind=params.has('kind')?(params.get('kind')==='all'?'':params.get('kind')):'data',study=params.get('study')||'',page=Math.max(1,Number(params.get('page'))||1);
