const facets=document.createElement('div');facets.className='subject-facets';facets.innerHTML=`<div class="filter-group"><label for="resource-type">Resource type</label><select id="resource-type"><option value="">All resources</option><option value="data">Data</option><option value="code">Code</option><option value="documentation">Documentation</option></select></div><div class="filter-group subject-group"><h3>Scientific subjects</h3><p class="catalog-count-note">Choose any matching subject. Counts show all studies / files.</p>${subjects.map(s=>`<label class="subject-choice"><input name="subject" type="checkbox" value="${s.id}" ${chosenSubjects.has(s.id)?'checked':''}><span><b>${esc(s.label)}</b><small>${data.filter(d=>d.subjects.includes(s.id)).length} studies · ${fileData.filter(f=>f.subjects.includes(s.id)).length.toLocaleString()} files</small></span></label>`).join('')}<a class="vocabulary-link" href="/metadata/subjects.json" download>Subject definitions · JSON ↓</a></div>`;filters.insertBefore(facets,categories);document.querySelector('#resource-type').value=resource;document.querySelector('#resource-type').onchange=e=>{resource=e.target.value;kind='';document.querySelector('#file-kind').value='';update();};document.querySelectorAll('[name=subject]').forEach(b=>b.onchange=()=>{b.checked?chosenSubjects.add(b.value):chosenSubjects.delete(b.value);update();});
document.querySelector('#study-filter').value=study;document.querySelector('#study-filter').onchange=e=>{study=e.target.value;update();};document.querySelector('#file-kind').value=kind;document.querySelector('#file-kind').onchange=e=>{kind=e.target.value;update();};for(const unit of ['studies','files'])document.querySelector('#'+unit+'-tab').onclick=()=>{content=unit;page=1;spatial=false;includeUnlocated=true;map?.remove();map=null;renderCatalog();};
document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{selected=selected===b.dataset.category?'':b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>{x.classList.toggle('selected',x.dataset.category===selected);x.setAttribute('aria-pressed',x.dataset.category===selected);});update();});
