document.querySelector('#sort').value=sort;document.querySelector('#sort').onchange=e=>{sort=e.target.value;update();};
document.querySelector('#reset').onclick=()=>{chosenSubjects.clear();resource='';selected='';query='';variables.clear();depth='';after='';before='';sort='depth';kind='';study='';page=1;spatial=false;includeUnlocated=true;map?.remove();map=null;renderCatalog();urlUpdate();};
document.querySelector('#list-view').onclick=()=>changeView('list');document.querySelector('#map-view').onclick=()=>changeView('map');
document.querySelector('#show-moorings').onchange=e=>{if(map&&mooringLayer){e.target.checked?mooringLayer.addTo(map):mooringLayer.remove();}};
document.querySelector('#spatial').onchange=e=>{spatial=e.target.checked;update();};document.querySelector('#include-unlocated').onchange=e=>{includeUnlocated=e.target.checked;update();};document.querySelector('#reset-map').onclick=()=>map?.setView([19.68,-80.06],12);
update(false);if(view==='map')initMap();
